package com.portfolio.features.portfolio.service; import com.portfolio.features.education.repository.EducationRepository; import com.portfolio.features.experience.repository.ExperienceRepository; import com.portfolio.features.project.repository.ProjectRepository; import com.portfolio.features.skill.repository.SkillRepository; import com.portfolio.features.social.repository.SocialLinkRepository; import com.portfolio.features.portfolio.dto.PortfolioCompletenessResponse; import com.portfolio.features.user.entity.AppUser; import java.util.*; import lombok.*; import org.springframework.stereotype.Service; @Service @RequiredArgsConstructor public class PortfolioCompletenessService {private final PortfolioAccessService access;private final ExperienceRepository experiences;private final EducationRepository educations;private final SkillRepository skills;private final ProjectRepository projects;private final SocialLinkRepository social;public PortfolioCompletenessResponse calculate(AppUser u){var p=access.mine(u);int score=0;var missing=new ArrayList<String>();if(p.getFullName()!=null&&!p.getFullName().isBlank()&&p.getHeadline()!=null&&!p.getHeadline().isBlank())score+=25;else missing.add("profile");if(experiences.existsByPortfolioId(p.getId()))score+=15;else missing.add("experience");if(educations.existsByPortfolioId(p.getId()))score+=10;else missing.add("education");if(skills.existsByPortfolioId(p.getId()))score+=15;else missing.add("skills");if(projects.existsByPortfolioId(p.getId()))score+=25;else missing.add("projects");if(social.existsByPortfolioId(p.getId()))score+=10;else missing.add("socialLinks");return new PortfolioCompletenessResponse(score,missing);}}
